use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a (year, month, day) civil date.
/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (year, month, day) = civil_from_days(days);
    // Keep the date exactly 10 characters (YYYY-MM-DD) even for
    // absurd clock values far beyond year 9999.
    let (year, month, day) = if year > 9999 {
        (9999, 12, 31)
    } else if year < 0 {
        (0, 1, 1)
    } else {
        (year, month, day)
    };
    let s = format!("{:04}-{:02}-{:02}", year, month, day);
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
